import{_ as i,c as e,o,a0 as a}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"it/blog/elite-goal-setting.md","filePath":"it/blog/elite-goal-setting.md"}');const l=i({name:"it/blog/elite-goal-setting.md"},[["render",function(i,t,l,n,r,s){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="definizione-degli-obiettivi-per-gli-atleti-d-39-elite" tabindex="-1">Definizione degli obiettivi per gli atleti d&#39;élite <a class="header-anchor" href="#definizione-degli-obiettivi-per-gli-atleti-d-39-elite" aria-label="Permalink to &quot;Definizione degli obiettivi per gli atleti d&amp;#39;élite&quot;">​</a></h1><p>Definire gli obiettivi sembra semplice: decidere cosa si vuole e impegnarsi per raggiungerlo. Ma la definizione degli obiettivi a livello d&#39;élite è più articolata. Gli obiettivi giusti accelerano lo sviluppo; quelli sbagliati creano frustrazione e stagnazione.</p><h2 id="oltre-gli-obiettivi-di-base" tabindex="-1">Oltre gli obiettivi di base <a class="header-anchor" href="#oltre-gli-obiettivi-di-base" aria-label="Permalink to &quot;Oltre gli obiettivi di base&quot;">​</a></h2><p>La maggior parte dei giocatori si pone degli obiettivi di risultato: &quot;Vincere il campionato regionale&quot;. Questi obiettivi presentano dei problemi:</p><ul><li>Non puoi controllare completamente i risultati</li><li>Creano pressione senza direzione</li><li>Il successo o il fallimento sono binari</li><li>Non guidano la pratica quotidiana</li></ul><p>La definizione degli obiettivi d&#39;élite va più in profondità.</p><h2 id="la-gerarchia-degli-obiettivi" tabindex="-1">La gerarchia degli obiettivi <a class="header-anchor" href="#la-gerarchia-degli-obiettivi" aria-label="Permalink to &quot;La gerarchia degli obiettivi&quot;">​</a></h2><h3 id="livello-1-obiettivi-da-sogno-1-5-anni" tabindex="-1">Livello 1: Obiettivi da sogno (1-5 anni) <a class="header-anchor" href="#livello-1-obiettivi-da-sogno-1-5-anni" aria-label="Permalink to &quot;Livello 1: Obiettivi da sogno (1-5 anni)&quot;">​</a></h3><p>Le tue aspirazioni più grandi:</p><ul><li>&quot;Competere a livello nazionale&quot;</li><li>&quot;Essere riconosciuto come un tiratore d&#39;élite&quot;</li><li>&quot;Vincere un campionato importante&quot;</li></ul><p>Forniscono direzione e motivazione, ma non sono attuabili quotidianamente.</p><h3 id="livello-2-obiettivi-di-prestazione-stagione-anno" tabindex="-1">Livello 2: Obiettivi di prestazione (stagione/anno) <a class="header-anchor" href="#livello-2-obiettivi-di-prestazione-stagione-anno" aria-label="Permalink to &quot;Livello 2: Obiettivi di prestazione (stagione/anno)&quot;">​</a></h3><p>Miglioramenti misurabili nel tuo gioco:</p><ul><li>&quot;Aumenta la precisione di tiro dal 60% al 70%&quot;</li><li>&quot;Ridurre gli errori non forzati del 25%&quot;</li><li>&quot;Sviluppa una plombée affidabile&quot;</li></ul><p>Sono fattori sotto il tuo controllo e misurabili.</p><h3 id="livello-3-obiettivi-di-processo-giornalieri-settimanali" tabindex="-1">Livello 3: Obiettivi di processo (giornalieri/settimanali) <a class="header-anchor" href="#livello-3-obiettivi-di-processo-giornalieri-settimanali" aria-label="Permalink to &quot;Livello 3: Obiettivi di processo (giornalieri/settimanali)&quot;">​</a></h3><p>Le azioni che guidano il miglioramento:</p><ul><li>&quot;Routine pre-tiro completa per ogni lancio&quot;</li><li>&quot;Pratica la visualizzazione per 10 minuti al giorno&quot;</li><li>&quot;Addestra la tecnica di tiro 3 volte a settimana&quot;</li></ul><p>Sono completamente controllabili e contribuiscono al raggiungimento degli obiettivi prestazionali.</p><h2 id="il-quadro-smart" tabindex="-1">Il quadro SMART+ <a class="header-anchor" href="#il-quadro-smart" aria-label="Permalink to &quot;Il quadro SMART+&quot;">​</a></h2><p>Vai oltre gli obiettivi SMART di base:</p><h3 id="specifico" tabindex="-1">Specifico <a class="header-anchor" href="#specifico" aria-label="Permalink to &quot;Specifico&quot;">​</a></h3><p>Non &quot;migliorare il mio puntamento&quot;, ma &quot;sviluppare un demi-portée coerente che atterra entro 30 cm dal bersaglio da 8 metri&quot;.</p><h3 id="misurabile" tabindex="-1">Misurabile <a class="header-anchor" href="#misurabile" aria-label="Permalink to &quot;Misurabile&quot;">​</a></h3><p>Definisci come monitorerai i progressi:</p><ul><li>Percentuali di successo</li><li>Metriche di coerenza</li><li>Marcatori di analisi video</li></ul><h3 id="raggiungibile-ma-impegnativo" tabindex="-1">Raggiungibile ma impegnativo <a class="header-anchor" href="#raggiungibile-ma-impegnativo" aria-label="Permalink to &quot;Raggiungibile ma impegnativo&quot;">​</a></h3><p>L&#39;obiettivo dovrebbe richiedere una crescita, ma essere realistico. Un tiratore con il 60% che punta al 65% è realizzabile; puntare al 90% è pura fantasia.</p><h3 id="pertinente" tabindex="-1">Pertinente <a class="header-anchor" href="#pertinente" aria-label="Permalink to &quot;Pertinente&quot;">​</a></h3><p>Gli obiettivi devono essere in linea con le tue aspirazioni più ampie e affrontare le debolezze reali, non solo ciò che è facile migliorare.</p><h3 id="limitato-nel-tempo" tabindex="-1">Limitato nel tempo <a class="header-anchor" href="#limitato-nel-tempo" aria-label="Permalink to &quot;Limitato nel tempo&quot;">​</a></h3><p>Stabilisci scadenze chiare:</p><ul><li>&quot;Entro la fine della stagione&quot;</li><li>&quot;Entro 3 mesi&quot;</li><li>&quot;Dal campionato nazionale&quot;</li></ul><h3 id="personalmente-significativo" tabindex="-1">+ Personalmente significativo <a class="header-anchor" href="#personalmente-significativo" aria-label="Permalink to &quot;+ Personalmente significativo&quot;">​</a></h3><p>L&#39;obiettivo deve interessare a TE, non solo al tuo allenatore o ai tuoi compagni di squadra. La motivazione interiore sostiene l&#39;impegno quando i progressi sono lenti.</p><h2 id="processo-vs-focus-sul-risultato" tabindex="-1">Processo vs. focus sul risultato <a class="header-anchor" href="#processo-vs-focus-sul-risultato" aria-label="Permalink to &quot;Processo vs. focus sul risultato&quot;">​</a></h2><h3 id="il-problema-con-gli-obiettivi-di-risultato" tabindex="-1">Il problema con gli obiettivi di risultato <a class="header-anchor" href="#il-problema-con-gli-obiettivi-di-risultato" aria-label="Permalink to &quot;Il problema con gli obiettivi di risultato&quot;">​</a></h3><p>&quot;Vincere la partita&quot; crea problemi:</p><ul><li>Ansia per cose che non puoi controllare</li><li>Distrazione dall&#39;esecuzione</li><li>Pensiero tutto o niente</li><li>Pressione senza guida</li></ul><h3 id="il-potere-degli-obiettivi-di-processo" tabindex="-1">Il potere degli obiettivi di processo <a class="header-anchor" href="#il-potere-degli-obiettivi-di-processo" aria-label="Permalink to &quot;Il potere degli obiettivi di processo&quot;">​</a></h3><p>&quot;Eseguire perfettamente la mia routine pre-tiro&quot; offre:</p><ul><li>Controllo completo</li><li>Messa a fuoco chiara</li><li>Feedback immediato</li><li>Si sviluppa naturalmente verso i risultati</li></ul><h3 id="l-39-equilibrio" tabindex="-1">L&#39;equilibrio <a class="header-anchor" href="#l-39-equilibrio" aria-label="Permalink to &quot;L&amp;#39;equilibrio&quot;">​</a></h3><p>Utilizza obiettivi di risultato per motivazione e direzione. Utilizza obiettivi di processo per l&#39;attenzione e l&#39;esecuzione quotidiane.</p><h2 id="definizione-degli-obiettivi-per-le-diverse-fasi" tabindex="-1">Definizione degli obiettivi per le diverse fasi <a class="header-anchor" href="#definizione-degli-obiettivi-per-le-diverse-fasi" aria-label="Permalink to &quot;Definizione degli obiettivi per le diverse fasi&quot;">​</a></h2><h3 id="fuori-stagione" tabindex="-1">Fuori stagione <a class="header-anchor" href="#fuori-stagione" aria-label="Permalink to &quot;Fuori stagione&quot;">​</a></h3><p>Concentrarsi sugli obiettivi di sviluppo:</p><ul><li>Miglioramenti tecnici</li><li>Condizionamento fisico</li><li>Sviluppo delle abilità mentali</li><li>Amplia la tua gamma di coperte</li></ul><h3 id="pre-stagione" tabindex="-1">Pre-stagione <a class="header-anchor" href="#pre-stagione" aria-label="Permalink to &quot;Pre-stagione&quot;">​</a></h3><p>Transizione all&#39;integrazione:</p><ul><li>Combinare le abilità in condizioni simili a quelle di una partita</li><li>Test dei miglioramenti nella competizione amichevole</li><li>Strategie di raffinamento</li></ul><h3 id="stagione-delle-competizioni" tabindex="-1">Stagione delle competizioni <a class="header-anchor" href="#stagione-delle-competizioni" aria-label="Permalink to &quot;Stagione delle competizioni&quot;">​</a></h3><p>Passaggio a performance e processo:</p><ul><li>Eseguire ciò che hai sviluppato</li><li>Obiettivi del processo per ogni partita</li><li>Modifiche tecniche minime</li></ul><h3 id="post-competizione" tabindex="-1">Post-Competizione <a class="header-anchor" href="#post-competizione" aria-label="Permalink to &quot;Post-Competizione&quot;">​</a></h3><p>Riflessione e pianificazione:</p><ul><li>Analizza cosa ha funzionato</li><li>Identificare le aree di crescita</li><li>Stabilisci obiettivi per il ciclo successivo</li></ul><h2 id="errori-comuni-nella-definizione-degli-obiettivi" tabindex="-1">Errori comuni nella definizione degli obiettivi <a class="header-anchor" href="#errori-comuni-nella-definizione-degli-obiettivi" aria-label="Permalink to &quot;Errori comuni nella definizione degli obiettivi&quot;">​</a></h2><h3 id="troppi-obiettivi" tabindex="-1">Troppi obiettivi <a class="header-anchor" href="#troppi-obiettivi" aria-label="Permalink to &quot;Troppi obiettivi&quot;">​</a></h3><p>La concentrazione è potere. 2-3 obiettivi chiave sono meglio di 10 obiettivi sparsi.</p><h3 id="solo-obiettivi-di-risultato" tabindex="-1">Solo obiettivi di risultato <a class="header-anchor" href="#solo-obiettivi-di-risultato" aria-label="Permalink to &quot;Solo obiettivi di risultato&quot;">​</a></h3><p>Senza obiettivi di processo non esiste una tabella di marcia.</p><h3 id="nessuna-flessibilita" tabindex="-1">Nessuna flessibilità <a class="header-anchor" href="#nessuna-flessibilita" aria-label="Permalink to &quot;Nessuna flessibilità&quot;">​</a></h3><p>Gli obiettivi devono adattarsi alle nuove informazioni. Rimanere fedeli a obiettivi obsoleti è uno spreco di energie.</p><h3 id="obiettivi-basati-sul-confronto" tabindex="-1">Obiettivi basati sul confronto <a class="header-anchor" href="#obiettivi-basati-sul-confronto" aria-label="Permalink to &quot;Obiettivi basati sul confronto&quot;">​</a></h3><p>&quot;Sii migliore di [giocatore]&quot; mette il tuo successo nelle mani di qualcun altro.</p><h3 id="trascurare-gli-obiettivi-mentali" tabindex="-1">Trascurare gli obiettivi mentali <a class="header-anchor" href="#trascurare-gli-obiettivi-mentali" aria-label="Permalink to &quot;Trascurare gli obiettivi mentali&quot;">​</a></h3><p>Gli obiettivi tecnici e fisici sono dominanti, ma spesso sono le capacità mentali a determinare chi vince.</p><h2 id="strategie-di-implementazione" tabindex="-1">Strategie di implementazione <a class="header-anchor" href="#strategie-di-implementazione" aria-label="Permalink to &quot;Strategie di implementazione&quot;">​</a></h2><h3 id="scrivili" tabindex="-1">Scrivili <a class="header-anchor" href="#scrivili" aria-label="Permalink to &quot;Scrivili&quot;">​</a></h3><p>Gli obiettivi scritti hanno molte più probabilità di essere raggiunti.</p><h3 id="rivedi-regolarmente" tabindex="-1">Rivedi regolarmente <a class="header-anchor" href="#rivedi-regolarmente" aria-label="Permalink to &quot;Rivedi regolarmente&quot;">​</a></h3><p>La revisione settimanale mantiene gli obiettivi presenti e consente di apportare modifiche.</p><h3 id="condividi-in-modo-selettivo" tabindex="-1">Condividi in modo selettivo <a class="header-anchor" href="#condividi-in-modo-selettivo" aria-label="Permalink to &quot;Condividi in modo selettivo&quot;">​</a></h3><p>Condividi con chi ti sosterrà, non con chi ti indebolirà.</p><h3 id="visualizza-il-risultato" tabindex="-1">Visualizza il risultato <a class="header-anchor" href="#visualizza-il-risultato" aria-label="Permalink to &quot;Visualizza il risultato&quot;">​</a></h3><p>Immagina regolarmente di raggiungere i tuoi obiettivi: la sensazione, il momento.</p><h3 id="monitorare-i-progressi" tabindex="-1">Monitorare i progressi <a class="header-anchor" href="#monitorare-i-progressi" aria-label="Permalink to &quot;Monitorare i progressi&quot;">​</a></h3><p>Ciò che viene misurato viene gestito. Tieni traccia dei dati.</p><h2 id="quando-gli-obiettivi-non-vengono-raggiunti" tabindex="-1">Quando gli obiettivi non vengono raggiunti <a class="header-anchor" href="#quando-gli-obiettivi-non-vengono-raggiunti" aria-label="Permalink to &quot;Quando gli obiettivi non vengono raggiunti&quot;">​</a></h2><p>Gli obiettivi non raggiunti non sono fallimenti, sono dati:</p><ol><li><strong>Analizza</strong>: Perché non è stato raggiunto l&#39;obiettivo?</li><li><strong>Impara</strong>: Cosa ti insegna questo?</li><li><strong>Regola</strong>: modifica l&#39;obiettivo o l&#39;approccio</li><li><strong>Continua</strong>: La perseveranza batte la perfezione</li></ol><h2 id="il-gioco-mentale-degli-obiettivi" tabindex="-1">Il gioco mentale degli obiettivi <a class="header-anchor" href="#il-gioco-mentale-degli-obiettivi" aria-label="Permalink to &quot;Il gioco mentale degli obiettivi&quot;">​</a></h2><p>Gli obiettivi influenzano la psicologia:</p><ul><li><strong>Troppo facile</strong>: Noia, compiacimento</li><li><strong>Troppo difficile</strong>: Ansia, scoraggiamento</li><li><strong>Perfetto</strong>: Coinvolgimento, flusso, crescita</li></ul><p>Trova il punto ideale in cui gli obiettivi sono stimolanti ma non opprimenti.</p><hr><p>| <em>Correlato: <a href="/it/istruzione/obiettivi/">Introduzione alla definizione degli obiettivi</a> | <a href="/it/istruzione/obiettivi/obiettivi-smart">Obiettivi SMART</a> | <a href="/it/istruzione/obiettivi/pianificazione">Pianificare il tuo sviluppo</a></em> |</p>',88)])])}]]);export{t as __pageData,l as default};
